"""
Implementation of dummy collectors
"""
from taf.collectors.core import StartableCollector
from taf.collectors.core.entities.async_collector import AsyncCollector


class DummyCollector(StartableCollector):
    def _collect(self, target_dir):
        pass

    def _start(self):
        pass

    def _stop(self):
        pass

    def _setup(self):
        pass

    def _teardown(self):
        pass


class DummyCollectorFactory:
    def create(self, configuration, existing_arguments):
        return DummyCollector(name=configuration["name"])


class DummyAsyncCollector(AsyncCollector):
    def _collect(self, target_dir):
        pass

    def _async_collect(self, target_dir):
        return []


class DummyAsyncCollectorFactory:
    def create(self, configuration, existing_arguments):
        return DummyAsyncCollector(name=configuration["name"])
